export type WaczCompleteness = {
    bodylessUrls: Array<string>;
    truncatedUrls: Array<string>;
    complete: boolean;
};

/**
 * Why a capture did not succeed. Absent on success.
 */
export type CaptureErrorDetails = {
    type: ErrorType;
    message: string;
    httpStatusCode?: number;
    httpStatusText?: string;
    timeoutMs?: number;
};

/**
 * What became of one capture task. Returned by
 * `GET /v1/captures/{taskId}` and written verbatim as the
 * `.result.json` manifest next to the artifacts, so a consumer can
 * parse either source with the same code.
 *
 */
export type CaptureResultReport = {
    taskId: string;
    /**
     * Echoed from the request, when one was provided.
     */
    correlationId?: string;
    url: string;
    labels: Array<string>;
    status: CaptureStatus;
    /**
     * HTTP status of the captured page's main response.
     */
    httpStatusCode?: number;
    timestamp: string;
    captureProcessingTimeMs: number;
    /**
     * How many retries the task had consumed when it finished.
     */
    retryCount: number;
    workerIndex: number;
    artifacts: CaptureArtifacts;
    waczStats?: WaczStats;
    completeness?: WaczCompleteness;
    signature?: WaczSignature;
    errorDetails?: CaptureErrorDetails;
};

/**
 * RFC 7807 Problem Details
 */
export type Problem = {
    type?: string;
    title: string;
    status: number;
    detail?: string;
    instance?: string;
};

export type WorkerHealth = 'ready' | 'busy' | 'error' | 'disconnected';

export type ErrorType = 'http' | 'timeout' | 'connection' | 'internal';

export type ErrorTaskInfo = {
    taskId: string;
    url: string;
    labels: Array<string>;
};

export type ErrorRecord = {
    type: ErrorType;
    message: string;
    httpStatusCode?: number;
    httpStatusText?: string;
    timeoutMs?: number;
    timestamp: string;
    task?: ErrorTaskInfo;
};

export type BrowserOptions = {
    /**
     * The configured browser endpoint, returned in WHATWG-canonical form (e.g. a trailing slash is added: `http://chromium-1:9222/`). The server parses the operator-supplied value into a URL, so the string echoed here is the normalized form, not necessarily the exact input.
     */
    browserUrl: string;
};

/**
 * Snapshot of the task a worker is currently processing. Present only
 * when the worker is in the `busy` health state. `elapsedMs` is
 * computed at response-build time as `now - startedAt`.
 *
 */
export type CurrentTask = {
    taskId: string;
    url: string;
    labels: Array<string>;
    correlationId?: string;
    startedAt: string;
    elapsedMs: number;
    retryCount: number;
};

export type WorkerInfo = {
    index: number;
    browserOptions: BrowserOptions;
    health: WorkerHealth;
    processedCount: number;
    errorCount: number;
    errorHistory: Array<ErrorRecord>;
    currentTask?: CurrentTask;
};

/**
 * Snapshot of a task waiting in the queue. `queuedMs` is computed at
 * response-build time as `now - enqueuedAt` and is preserved across
 * retries (so a task stuck in retry loops shows its true total age).
 *
 */
export type PendingTask = {
    taskId: string;
    url: string;
    labels: Array<string>;
    correlationId?: string;
    enqueuedAt: string;
    queuedMs: number;
    retryCount: number;
};

/**
 * Snapshot of a task currently being processed by a worker. Mirrors
 * `PendingTask` but adds `workerIndex`, `startedAt`, and
 * `elapsedMs` so callers can correlate the processing task with the
 * owning worker and see how long it has been running.
 *
 */
export type ProcessingTask = {
    taskId: string;
    url: string;
    labels: Array<string>;
    correlationId?: string;
    enqueuedAt: string;
    queuedMs: number;
    retryCount: number;
    workerIndex: number;
    startedAt: string;
    elapsedMs: number;
};

/**
 * Container for runtime queue introspection. `pendingTasks` is the
 * head of the pending queue; `processingTasks` is the set of tasks
 * currently held by busy workers (one per busy worker).
 *
 */
export type QueueSnapshot = {
    pendingTasks: Array<PendingTask>;
    processingTasks: Array<ProcessingTask>;
};

export type StatusResponse = {
    pending: number;
    processing: number;
    /**
     * Tasks that finished with a capture and uploaded artifacts.
     *
     */
    succeeded: number;
    /**
     * Tasks the server gave up on after exhausting the retry budget.
     * Counted separately from `succeeded` because the two are not
     * interchangeable: a client reconciling its own records needs to
     * know which tasks will never produce an artifact.
     *
     */
    failed: number;
    operationalWorkers: number;
    totalWorkers: number;
    isRunning: boolean;
    isDegraded: boolean;
    workers: Array<WorkerInfo>;
    queue: QueueSnapshot;
    /**
     * Build fingerprint baked in at build time (src/generated/version.ts).
     * Use `revision` to confirm the running server matches a given source:
     * `revision === $(git rev-parse --short HEAD)`.
     *
     */
    build: {
        /**
         * BrowserHive package version (package.json).
         */
        version: string;
        /**
         * Short git commit the image was built from — passed at build time
         * via `GIT_REV` (Docker) or read from git (host). `"dev"` when
         * neither was available.
         *
         */
        revision: string;
        /**
         * When this build was produced. Changes every build.
         */
        buildTime: string;
    };
};

export type SubmitCaptureData = {
    body: CaptureRequest;
    path?: never;
    query?: never;
    url: '/v1/captures';
};

export type SubmitCaptureErrors = {
    /**
     * Validation failure
     */
    400: Problem;
    /**
     * URL already in queue (when rejectDuplicateUrls is enabled)
     */
    409: Problem;
    /**
     * No operational workers available
     */
    503: Problem;
};

export type SubmitCaptureError = SubmitCaptureErrors[keyof SubmitCaptureErrors];

export type SubmitCaptureResponses = {
    /**
     * Request accepted for processing
     */
    202: CaptureAcceptance;
};

export type SubmitCaptureResponse = SubmitCaptureResponses[keyof SubmitCaptureResponses];

export type GetCaptureData = {
    body?: never;
    path: {
        /**
         * The `taskId` returned by `POST /v1/captures`.
         */
        taskId: string;
    };
    query?: never;
    url: '/v1/captures/{taskId}';
};

export type GetCaptureErrors = {
    /**
     * No such task, or the result was evicted from the bounded cache.
     * These are deliberately not distinguished: the server no longer
     * holds the information needed to tell them apart.
     *
     */
    404: Problem;
};

export type GetCaptureError = GetCaptureErrors[keyof GetCaptureErrors];

export type GetCaptureResponses = {
    /**
     * The task finished and its result is still cached
     */
    200: CaptureResultReport;
    /**
     * The task is still pending or being processed. The body is empty —
     * there is nothing to report yet.
     *
     */
    202: unknown;
};

export type GetCaptureResponse = GetCaptureResponses[keyof GetCaptureResponses];

export type GetStatusData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Maximum number of pending tasks to include in
         * `queue.pendingTasks`. Defaults to 50; clamp at 200 to bound the
         * response size.
         *
         */
        pendingLimit?: number;
    };
    url: '/v1/status';
};

export type GetStatusErrors = {
    /**
     * Invalid query parameter
     */
    400: Problem;
};

export type GetStatusError = GetStatusErrors[keyof GetStatusErrors];

export type GetStatusResponses = {
    /**
     * Current status of queue and workers
     */
    200: StatusResponse;
};

export type GetStatusResponse = GetStatusResponses[keyof GetStatusResponses];
